<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Controllers\Controller;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;
class CountryController extends Controller{public function index():JsonResponse{return response()->json(['data'=>DB::table('countries')->where('active',true)->get()]);}public function updateCompany(Request $request):JsonResponse{abort_unless($request->user()->account_type==='company',403);$data=$request->validate(['country_code'=>['required',Rule::exists('countries','code')->where('active',true)]]);$company=$request->user()->companies()->wherePivot('status','active')->firstOrFail();$role=$company->members()->whereKey($request->user()->id)->first()?->pivot->role;abort_unless(in_array($role,['owner','admin']),403);$company->update($data);return response()->json(['data'=>$company,'message'=>'País operativo actualizado.']);}}
